
public class Arrays {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
 
		// Arrays - Multiple Values in one Single Variable 
		
		// Syntax - 1 (to Create an Array)
		int[] arr1 = new int[5];  // Assigning 5 values in the memory with the help of new keyword 
		
		arr1[0] = 9;
		arr1[1] = 8;
		arr1[2] = 7;
		arr1[3] = 6;
		arr1[4] = 5; 
		
		
		
		// Syntax - 2 (to Create an Array)
		
		int[] arr2 = {1,2,3,4,5,6};
		System.out.println(arr2[3]);
		
		
		
		// Strings 
		
		String [] value = {"aditya","Vshk","123","t"};
	    System.out.println(value[0]);
	    System.out.println(value[1]);
	    System.out.println(value[2]);
	    
	}

}
